#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=8

# Run from the repo root so .env lands next to build.gradle, wherever we're called from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

banner "World GDrive Sync: Google OAuth client setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "The shared Google account"
say "Every friend in the group signs the mod into ONE Google account (ADR-0001)."
say "Its password gets shared, so make it a dedicated account that holds nothing else."
if confirm "Do you still need to create that account?"; then
  open_url "https://accounts.google.com/signup"
  step "Create the account (a plain @gmail.com one is fine)."
  step "Save its password somewhere the group can reach it."
  pause "Press Enter once the account exists."
else
  note "Skipping: the account already exists."
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create a Google Cloud project"
note "The project can belong to your own Google account; it doesn't have to be the shared one."
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: something neutral like Coop World Saves. Leave the organization as is."
warn "Keep Google, Drive, GDrive, Minecraft and other brand names out of the project name and ID:"
note "Google's abuse checks can flag a project for them, and the project ID can't be changed later."
step "Click Create and wait for the notification saying it's ready."
step "In the project picker at the top of the console, select the new project."
warn "Every remaining stage happens inside this project, so check that the picker shows it."
pause "Press Enter once the new project is selected."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Enable the Google Drive API"
open_url "https://console.cloud.google.com/apis/library/drive.googleapis.com"
step "Confirm the project picker still shows your new project."
step "Click Enable. (If the button says Manage, it's already on.)"
pause "Press Enter once the Drive API is enabled."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Consent screen (Google Auth Platform)"
open_url "https://console.cloud.google.com/auth/overview"
step "Click Get started. (If you see Branding/Audience/Clients on the left, it's done: skip to the scope step.)"
step "App information: App name Coop World Saves (no Google/Drive/Minecraft), User support email: your email → Next."
step "Audience: External → Next."
step "Contact information: your email → Next → tick the user data policy → Create."
warn "Don't upload a logo: a logo means Google has to verify the brand before you can publish."
say ""
step "Left menu → Data Access → Add or remove scopes."
step "Under 'Manually add scopes' paste:  https://www.googleapis.com/auth/drive.file"
step "Add to table → Update → Save at the bottom of the Data Access page."
note "drive.file only lets the mod see files it created itself; it's a non-sensitive scope."
pause "Press Enter once the drive.file scope is saved."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Publish the app to production"
say "In Testing mode, sign-ins expire after 7 days and every player has to be added as a test user."
open_url "https://console.cloud.google.com/auth/audience"
step "Under Publishing status (it should say Testing), click Publish app."
if confirm "Publish the app to production now? (You can switch it back to Testing later.)"; then
  step "Click Confirm in Google's dialog."
  note "Players may still see Google's 'unverified app' page; Advanced → Go to … gets past it."
  pause "Press Enter once the status says In production."
else
  SKIPPED+=("Publish the app to production (Auth Platform → Audience → Publish app), or sign-ins expire after 7 days")
  warn "Left in Testing: only listed test users can sign in (others get 'Error 403: access_denied')."
  step "On this same Audience page, under Test users: Add users → the shared account's address → Save."
  note "Test-user sign-ins expire every 7 days until the app is published."
  pause "Press Enter once the shared account is listed as a test user."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Create the Desktop app OAuth client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Desktop app. Name: Coop World Saves client."
step "Click Create. A dialog shows the Client ID and the Client secret."
warn "Google shows the secret only in this dialog. Click Download JSON as a backup, and keep it out of the repo."
say ""
while true; do
  ask GDRIVE_CLIENT_ID "Paste the Client ID:"
  [[ "$GDRIVE_CLIENT_ID" == *.apps.googleusercontent.com ]] && break
  warn "That doesn't end in .apps.googleusercontent.com, so try again."
done
while true; do
  ask_secret GDRIVE_CLIENT_SECRET "Paste the Client secret (hidden):"
  [[ -n "$GDRIVE_CLIENT_SECRET" ]] && break
  warn "The secret can't be empty."
done
write_env GDRIVE_CLIENT_ID "$GDRIVE_CLIENT_ID"
write_env GDRIVE_CLIENT_SECRET "$GDRIVE_CLIENT_SECRET"
note "build.gradle reads these from .env (gitignored) and builds them into the mod."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Give CI the client"
say "The GitHub Actions build (build.yml) reads GDRIVE_CLIENT_ID and GDRIVE_CLIENT_SECRET"
say "from repo secrets, so the jars it uploads can sign in."
note "Anyone who can download those build artifacts can pull the client out of the jar."
note "Google treats Desktop app secrets as non-confidential, so that's acceptable."
if confirm "Set both as GitHub repo secrets now?"; then
  set_secret GDRIVE_CLIENT_ID "$GDRIVE_CLIENT_ID"
  set_secret GDRIVE_CLIENT_SECRET "$GDRIVE_CLIENT_SECRET"
else
  SKIPPED+=("GitHub secrets GDRIVE_CLIENT_ID / GDRIVE_CLIENT_SECRET (CI builds ship without sign-in until set)")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check that sign-in works"
say "Launch the dev client, then:"
step "Title screen → Shared Worlds → sign in."
step "In the browser, sign in as the SHARED account (stage 1) and allow access."
step "If Google says the app isn't verified: Advanced → Go to Coop World Saves."
step "Back in the game, the Shared Worlds screen should show you as signed in."
if confirm "Run ./gradlew runClient now?"; then
  ./gradlew runClient || warn "runClient exited with an error; check the Gradle output above."
else
  note "Run it later with: ./gradlew runClient"
fi
pause

finish
}

run_wizard "$@"; exit
